function behavior(screenshots) {
  const json = JSON.stringify(screenshots).replace(/</g, '\\u003c');
  return `<style>${supplementaryStyles()}</style><script>
const screenshots=${json};
const tabs=[...document.querySelectorAll('[data-report-tab]')];const panels=[...document.querySelectorAll('[data-panel-view]')];
function selectTab(name){tabs.forEach(tab=>tab.classList.toggle('active',tab.dataset.reportTab===name));panels.forEach(panel=>panel.hidden=panel.dataset.panelView!==name);}
tabs.forEach(tab=>tab.addEventListener('click',()=>selectTab(tab.dataset.reportTab)));
function selectStep(index){const value=Number(index);document.querySelectorAll('[data-step]').forEach(row=>row.classList.toggle('active',Number(row.dataset.step)===value));document.querySelectorAll('[data-step-detail]').forEach(detail=>detail.hidden=Number(detail.dataset.stepDetail)!==value);}
document.querySelectorAll('[data-step]').forEach(row=>row.addEventListener('click',()=>selectStep(row.dataset.step)));
document.querySelectorAll('[data-jump-step],[data-knowledge-step]').forEach(button=>button.addEventListener('click',()=>{selectTab('process');selectStep(button.dataset.jumpStep??button.dataset.knowledgeStep);document.querySelector('.process-layout')?.scrollIntoView({block:'start'});}));
const logButtons=[...document.querySelectorAll('[data-log-filter]')];const logRows=[...document.querySelectorAll('.log-line')];const logSearch=document.querySelector('[data-log-search]');
function updateLogContext(row){if(!row)return;document.querySelectorAll('.log-line').forEach(item=>item.classList.toggle('active',item===row));const title=document.querySelector('[data-context-title]');if(title)title.textContent=row.querySelector('b')?.textContent||'日志';['operationId','decisionId','queryId','sceneId','generation','app','layout'].forEach(field=>{const target=document.querySelector('[data-context-field="'+(field==='app'?'App':field)+'"]');if(target)target.textContent=row.dataset[field]||'-';});}
function filterLogs(){const active=document.querySelector('[data-log-filter].active')?.dataset.logFilter||'ALL';const query=(logSearch?.value||'').trim().toLowerCase();let visible=0;logRows.forEach(row=>{const show=(active==='ALL'||row.dataset.logCategory===active)&&(!query||row.dataset.logText.includes(query));row.hidden=!show;if(show)visible++;});const count=document.querySelector('[data-log-visible]');if(count)count.textContent=visible;const empty=document.querySelector('.log-empty');if(empty)empty.hidden=visible>0;}
logButtons.forEach(button=>button.addEventListener('click',()=>{logButtons.forEach(item=>item.classList.toggle('active',item===button));filterLogs();}));logSearch?.addEventListener('input',filterLogs);logRows.forEach(row=>row.addEventListener('click',()=>updateLogContext(row)));if(logRows[0])updateLogContext(logRows[0]);
document.querySelectorAll('[data-step-logs]').forEach(button=>button.addEventListener('click',()=>{selectTab('logs');const id=button.dataset.stepLogs;logSearch.value=id;filterLogs();}));
document.querySelector('[data-export-logs]')?.addEventListener('click',()=>{const text=logRows.filter(row=>!row.hidden).map(row=>[row.querySelector('time')?.textContent,row.querySelector('em')?.textContent,row.querySelector('b')?.textContent,row.querySelector('code')?.textContent].join('\\t')).join('\\n');const blob=new Blob([text],{type:'text/plain;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='execution-logs.txt';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),0);});
let currentShot=0,scale=1,viewMode='fit',dragging=false,dragX=0,dragY=0,scrollX=0,scrollY=0;const dialog=document.getElementById('shot-dialog'),stage=document.getElementById('viewer-stage'),canvas=document.getElementById('viewer-canvas'),frame=document.getElementById('viewer-frame'),image=document.getElementById('viewer-image'),overlay=document.getElementById('viewer-overlay'),scaleOutput=document.getElementById('viewer-scale');
function centerViewer(){stage.scrollLeft=Math.max(0,(canvas.scrollWidth-stage.clientWidth)/2);stage.scrollTop=Math.max(0,(canvas.scrollHeight-stage.clientHeight)/2)}
function fitScale(){if(!image.naturalWidth||!image.naturalHeight)return 1;return Math.min(1,(stage.clientWidth-48)/image.naturalWidth,(stage.clientHeight-48)/image.naturalHeight)}
function applyScale(){const base=viewMode==='fit'?fitScale():scale;const w=Math.max(1,image.naturalWidth*base),h=Math.max(1,image.naturalHeight*base);canvas.style.width=Math.max(stage.clientWidth,w)+'px';canvas.style.height=Math.max(stage.clientHeight,h)+'px';frame.style.width=w+'px';frame.style.height=h+'px';scaleOutput.textContent=Math.round(base*100)+'%';requestAnimationFrame(centerViewer)}
function showShot(index,open=true){if(!screenshots.length)return;currentShot=(Number(index)+screenshots.length)%screenshots.length;const shot=screenshots[currentShot];scale=1;viewMode='fit';image.src=shot.src;image.alt=shot.title||'执行截图';if(shot.overlaySrc){overlay.src=shot.overlaySrc;overlay.hidden=false}else{overlay.removeAttribute('src');overlay.hidden=true}document.getElementById('viewer-title').textContent=shot.title||shot.ref;document.getElementById('viewer-meta').textContent=(currentShot+1)+' / '+screenshots.length+' · '+(shot.time||'');if(open&&!dialog.open)dialog.showModal();requestAnimationFrame(applyScale)}
image.addEventListener('load',applyScale);document.querySelectorAll('[data-shot]').forEach(button=>button.addEventListener('click',()=>showShot(button.dataset.shot)));
document.getElementById('close-viewer').addEventListener('click',()=>dialog.close());document.getElementById('previous-shot').addEventListener('click',()=>showShot(currentShot-1,false));document.getElementById('next-shot').addEventListener('click',()=>showShot(currentShot+1,false));document.getElementById('zoom-in').addEventListener('click',()=>{viewMode='zoom';scale=Math.min(4,(viewMode==='fit'?fitScale():scale)+.25);applyScale()});document.getElementById('zoom-out').addEventListener('click',()=>{viewMode='zoom';scale=Math.max(.1,scale-.25);applyScale()});document.getElementById('fit-image').addEventListener('click',()=>{viewMode='fit';applyScale()});document.getElementById('actual-image').addEventListener('click',()=>{viewMode='actual';scale=1;applyScale()});
stage.addEventListener('pointerdown',event=>{if(event.button!==0)return;dragging=true;dragX=event.clientX;dragY=event.clientY;scrollX=stage.scrollLeft;scrollY=stage.scrollTop;stage.classList.add('dragging');stage.setPointerCapture(event.pointerId);event.preventDefault()});stage.addEventListener('pointermove',event=>{if(!dragging)return;stage.scrollLeft=scrollX-(event.clientX-dragX);stage.scrollTop=scrollY-(event.clientY-dragY)});function stopDragging(event){if(!dragging)return;dragging=false;stage.classList.remove('dragging');if(stage.hasPointerCapture(event.pointerId))stage.releasePointerCapture(event.pointerId)}stage.addEventListener('pointerup',stopDragging);stage.addEventListener('pointercancel',stopDragging);dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});document.addEventListener('keydown',event=>{if(!dialog.open)return;if(event.key==='ArrowLeft')showShot(currentShot-1,false);if(event.key==='ArrowRight')showShot(currentShot+1,false)});window.addEventListener('resize',()=>{if(dialog.open)applyScale()});
</script>`;
}

function supplementaryStyles() {
  return `.step-expectations{display:grid;gap:5px;margin:0 0 14px}.step-expectations>div{display:flex;justify-content:space-between;gap:12px;padding:7px 9px;border-left:3px solid var(--pass);background:var(--pass-soft);font-size:9px}.step-expectations>div.fail,.step-expectations>div.blocked{border-color:var(--fail);background:var(--fail-soft)}.step-expectations span{color:var(--muted)}.action-details{display:grid;grid-template-columns:130px minmax(0,1fr);margin:0 0 14px;border:1px solid var(--line);background:var(--surface-2)}.action-kind{padding:10px;border-right:1px solid var(--line)}.action-kind span,.action-kind b{display:block}.action-kind span{color:var(--muted);font-size:8px}.action-kind b{margin-top:2px;font-size:11px}.action-details dl{display:flex;flex-wrap:wrap;gap:8px 18px;margin:0;padding:9px 11px}.action-details dt{color:var(--muted);font-size:8px}.action-details dd{margin:1px 0 0;font:9px ui-monospace,SFMono-Regular,Menlo,monospace;overflow-wrap:anywhere}.unlinked-knowledge{padding:16px 20px;border-top:1px solid var(--line)}.unlinked-knowledge>header{display:flex;justify-content:space-between;margin-bottom:10px}.unlinked-knowledge>header span{color:var(--muted);font-size:9px}@media(max-width:620px){.action-details{grid-template-columns:1fr}.action-kind{border-right:0;border-bottom:1px solid var(--line)}}`;
}

function renderCurrentContextHtml(caseJson, report) {
  const trace = buildExecutionTrace(report);
  const narrative = trace.narrative;
  const shots = screenshotModel(report, trace);
  const platform = report.execution?.platform || report.execution?.targetBinding?.platform || 'harmony';
  const platformLabel = PLATFORM_LABELS[platform] || platform;
  const display = report.display || {};
  const verdict = display.verdict || display.status || 'NOT_RUN';
  const passed = (narrative.checks || []).filter((check) => check.status === 'PASS').length;
  const sourceSha = report.execution?.sourceSha || caseJson.identity?.sourceSha || '-';
  const tabs = [['overview', '结果概览'], ['source', '原始用例'], ['understanding', '用例理解'], ['plan', '执行计划'], ['process', '执行过程'], ['logs', '详细日志']];
  const sourcePanel = `<section class="report-panel document-panel" data-panel-view="source" hidden><div class="document-meta"><span>原始内容</span><b>source.md</b><small>SHA-256 ${escapeHtml(String(sourceSha).slice(0, 12))}</small></div><article class="case-document">${renderSourceMarkdown(report.sourceText || '')}</article></section>`;
  return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(caseJson.identity?.title || '未命名用例')} - 执行报告</title><style>${styles()}</style></head><body><div class="product-shell"><header class="product-bar"><a class="product-brand" href="../../../../index.html"><span>MV</span><div><b>MAVT</b><small>移动端 AI 视觉测试</small></div></a><div><b>执行报告</b><small>${escapeHtml(report.execution?.batchId || report.execution?.executionId || '-')}</small></div></header><main class="workspace"><div class="report-page" data-platform="${escapeHtml(platform)}"><header class="report-head"><a class="back-button" href="../../../../index.html">${icon('arrowLeft')}返回总览</a><div class="report-title"><span>${escapeHtml(platformLabel)} · 用例 ${escapeHtml(caseJson.identity?.caseNo || '-')}</span><h1>${escapeHtml(caseJson.identity?.title || '未命名用例')}</h1><small>${escapeHtml(report.execution?.executionId || '-')}</small></div><div class="report-result"><span class="status status-${escapeHtml(className(verdict))}"><i></i>${escapeHtml(label(VERDICT_LABELS, verdict, '未知'))}</span><span><b>${passed}/${narrative.checks?.length || 0}</b>验证点</span><span><b>${escapeHtml(formatDuration(display.durationMs))}</b>总耗时</span></div></header><nav class="report-tabs" aria-label="报告内容">${tabs.map(([key, text], index) => `<button type="button" role="tab" class="${index === 0 ? 'active' : ''}" aria-selected="${index === 0}" data-report-tab="${key}" data-panel="${key}-panel">${text}${key === 'logs' ? `<i>${trace.entries.length}</i>` : ''}</button>`).join('')}</nav><div class="report-content">${renderOutcome(report, trace, narrative)}${sourcePanel}${renderUnderstanding(narrative)}${renderPlan(narrative)}${renderProcess(report, trace, narrative, shots)}${renderLogs(report, trace)}</div>${shotViewer()}</div></main></div>${behavior(shots)}</body></html>\n`;
}

module.exports = { renderCurrentContextHtml };
